class PageIterator:
    def __init__(self, fetch_page):
        # Eagerly loads every page up front - fix this.
        self.items = []
        cursor = None
        while True:
            resp = fetch_page(cursor)
            self.items.extend(resp['items'])
            cursor = resp['next']
            if cursor is None:
                break

    def __iter__(self):
        return iter(self.items)


