from collections import deque


class PageIterator:
    def __init__(self, fetch_page):
        self._fetch = fetch_page
        self._buffer = deque()
        self._cursor = None
        self._done = False

    def __iter__(self):
        return self

    def __next__(self):
        while not self._buffer:
            if self._done:
                raise StopIteration
            resp = self._fetch(self._cursor)
            self._buffer.extend(resp['items'])
            self._cursor = resp['next']
            self._done = self._cursor is None
        return self._buffer.popleft()


# ---------------------------------------------------------------------------
# Test harness (do not change). `pages` simulates the API: page i holds pages[i]
# and points to i+1 (None after the last page).
# ---------------------------------------------------------------------------
def simulate(pages, take=None):
    from itertools import islice
    fetched = []

    def fetch_page(cursor):
        idx = 0 if cursor is None else cursor
        fetched.append(idx)
        nxt = idx + 1 if idx + 1 < len(pages) else None
        return {"items": list(pages[idx]), "next": nxt}

    it = PageIterator(fetch_page)
    items = list(islice(it, take)) if take is not None else list(it)
    return {"items": items, "fetched": fetched, "iter_is_self": iter(it) is it,
            "exhausted_again": list(it) == [] if take is None else None}
